    ctx.fillStyle='rgba(220,230,240,.85)';ctx.font='10px sans-serif';ctx.textAlign='right';for(let cm=1;cm<depth;cm++){const y=cm*pxcm;ctx.fillRect(COLS-(cm%5?5:9),y,cm%5?5:9,1);if(cm%5===0)ctx.fillText(cm+'',COLS-11,y+3);}
